let _pass = 0;
let _fail = 0;
function _test(num: number, got: any, expected: any) {
  const passed = got === expected;
  console.log('---------------------');
  console.log('Test ' + num + ':');
  console.log('Output: ' + got);
  console.log(passed ? 'Pass' : 'Fail');
  if (passed) _pass++; else _fail++;
}
const ch = new Channel('Steve\'s Channel');
_test(1, ch.name, 'Steve\'s Channel');
_test(2, ch.getSubscribers(), 0);
ch.subscribe();
_test(3, ch.getSubscribers(), 1);
ch.subscribe();
ch.subscribe();
_test(4, ch.getSubscribers(), 3);
const ch2 = new Channel('MeTube Official');
_test(5, ch2.getSubscribers(), 0);
ch2.subscribe();
_test(6, ch2.getSubscribers(), 1);
console.log('---------------------');
console.log(_pass + ' passed, ' + _fail + ' failed');

